import sys
from itertools import combinations

def is_prime(x):
    if x < 2:
        return False
    d = 2
    while d * d <= x:
        if x % d == 0:
            return False
        d += 1
    return True

data = sys.stdin.read().split()
n, N = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
best = None
bestsel = None
for sel in combinations(range(n), N):
    s = set(sel)
    ok = True
    for i in sel:
        if a[i] % 2 == 0 and a[i] != 2:
            if i + 1 >= n or (i + 1) not in s:
                ok = False
                break
        if is_prime(a[i]) and (i + 1) in s:
            ok = False
            break
    if ok:
        tot = sum(a[i] for i in sel)
        if best is None or tot > best:
            best = tot
            bestsel = sel
if best is None:
    print(-1)
else:
    print(' '.join(str(a[i]) for i in bestsel))

